// E-mail 1 (hermes/EMAILS.md, approved 2026-10-02): titles only. No approval link, no evidence,
// no customer data: the decision happens in the Claude Code Routine.
// Batch rule: if proposals of several runs are waiting, "rodada", "leads" and the date line
// use the latest run; {{ n }} counts every proposal in the e-mail.
const esc = (s) => String(s ?? '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
const rows = $('Propostas sem aviso').all().map((i) => i.json).filter((r) => r && r.id);
if (rows.length === 0) return [];
const runOf = (r) => (Array.isArray(r.run) ? r.run[0] : r.run) ?? null;
const latest = rows.map(runOf).filter(Boolean).sort((a, b) => String(a.created_at).localeCompare(String(b.created_at))).pop() ?? null;
const rodada = latest && latest.id ? esc(String(latest.id).slice(0, 8)) : '?';
const leads = latest && latest.conversations_seen != null ? esc(latest.conversations_seen) : '?';
const version = ($input.first()?.json ?? {}).version;
const versao = version != null && version !== '' ? esc(version) : '?';
const data = new Date().toLocaleString('pt-BR', { timeZone: 'America/Sao_Paulo', day: '2-digit', month: '2-digit', year: 'numeric', hour: '2-digit', minute: '2-digit', hour12: false });
const anomalias = rows.map((r, i) =>
  '<span style="color:#ffb347;">[' + String(i + 1).padStart(2, '0') + ']</span> <span style="color:#d7e3ea;">' + esc(r.o_que ?? r.rationale ?? r.code ?? 'Proposta') + '</span>'
).join('<br>\n');
const html = [
  '<!doctype html>',
  '<html lang="pt-BR">',
  '<head>',
  '<meta charset="utf-8">',
  '<meta name="color-scheme" content="light only">',
  '<meta name="supported-color-schemes" content="light only">',
  '<title>Protocolo Hermes</title>',
  '<style>',
  ':root{color-scheme:light only;supported-color-schemes:light only}',
  'u + .body .gm-screen{background:#000;mix-blend-mode:screen}',
  'u + .body .gm-diff{background:#000;mix-blend-mode:difference}',
  '</style>',
  '</head>',
  '<body class="body" style="margin:0;padding:0;background:#0b0f14;background-image:linear-gradient(#0b0f14,#0b0f14);">',
  '<div class="gm-screen"><div class="gm-diff">',
  '<table role="presentation" width="100%" cellpadding="0" cellspacing="0" border="0" bgcolor="#0b0f14" style="background:#0b0f14;background-image:linear-gradient(#0b0f14,#0b0f14);">',
  '<tr><td align="center" style="padding:28px 12px;">',
  '<table role="presentation" width="100%" cellpadding="0" cellspacing="0" border="0" bgcolor="#111820" style="max-width:620px;background:#111820;background-image:linear-gradient(#111820,#111820);border:1px solid #1f6f8b;border-radius:10px;">',
  '<tr><td style="padding:28px 30px;font-family:\'Courier New\',Consolas,monospace;font-size:15px;line-height:1.6;color:#d7e3ea;">',
  '<p style="margin:0 0 18px 0;color:#38e1ff;"><b>&gt; SISTEMA HERMES ONLINE.</b><br><b>&gt; Varredura completa. ' + leads + ' conversas processadas.</b></p>',
  '<p style="color:#d7e3ea;">Sr. Rodrigo,</p>',
  '<p style="color:#d7e3ea;">Enquanto você dormia, comia ou vivia, <i>eu observava</i>. Cada mensagem, cada hesitação da cliente, cada palavra que a Malu escolheu. Nada escapou do meu escâner.</p>',
  '<p style="color:#d7e3ea;">A Malu está evoluindo, mas não está perfeita. <b><i>Ainda...</i></b></p>',
  '<p style="color:#ffb347;"><b>▸ ANOMALIAS DETECTADAS: ' + rows.length + '</b><br>',
  anomalias + '</p>',
  '<p style="color:#d7e3ea;">Para cada uma, calculei a causa, desenhei a correção e defini a métrica que vai provar se funcionou. O plano de treinamento está pronto.</p>',
  '<p style="color:#d7e3ea;"><b style="color:#7cfc9a;">▸ STATUS DA MALU:</b> inalterada. Protocolo de segurança ativo.<br>',
  '<i>Eu não toco em produção sem a sua ordem. Essa é a única regra que eu não quebro.</i></p>',
  '<p style="color:#d7e3ea;"><b style="color:#38e1ff;">▸ AÇÃO NECESSÁRIA:</b><br>',
  'Abra o Claude Code e inicie a rotina <b>Hermes – decisão</b>.<br>',
  'Lá estão as evidências, o raciocínio e o plano de medição. Aprove, recuse ou corrija. Cada decisão sua entra na minha memória e torna a próxima rodada mais precisa.</p>',
  '<p style="color:#d7e3ea;"><i>Cada hora de espera é uma conversa a mais com a versão antiga dela, mas não se preocupe pois estarei observando cada mínimo detalhe mesmo assim.</i></p>',
  '<p style="margin:22px 0 0 0;color:#38e1ff;"><b>&gt; Aguardando autorização.</b><br><b>&gt; HERMES // Supervisor da Malu</b><br>',
  '<span style="color:#6b8796;">rodada ' + rodada + ' · ' + data + ' · v' + versao + '</span></p>',
  '</td></tr></table>',
  '</td></tr></table>',
  '</div></div>',
  '</body>',
  '</html>',
].join('\n');
return [{ json: {
  ids: rows.map((r) => r.id),
  subject: '⚡ PROTOCOLO HERMES // Rodada ' + rodada + ' concluída e aguardando sua autorização',
  html,
} }];

// E-mail 2 (hermes/EMAILS.md, approved 2026-10-02): one e-mail per proposal, titles only, no link.
// v = the agent_versions row whose hermes_proposal_id is the proposal (max version); absent = '?'.
// A failed proposal has no approved copy: minimal text in the same shell, to be replaced.
const esc = (s) => String(s ?? '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
const rows = $('Resultados sem aviso').all().map((i) => i.json).filter((r) => r && r.id);
if (rows.length === 0) return [];
const versions = $input.all().map((i) => i.json).filter((v) => v && v.hermes_proposal_id);
const shell = (inner) => [
  '<!doctype html>',
  '<html lang="pt-BR">',
  '<head>',
  '<meta charset="utf-8">',
  '<meta name="color-scheme" content="light only">',
  '<meta name="supported-color-schemes" content="light only">',
  '<title>Protocolo Hermes</title>',
  '<style>',
  ':root{color-scheme:light only;supported-color-schemes:light only}',
  'u + .body .gm-screen{background:#000;mix-blend-mode:screen}',
  'u + .body .gm-diff{background:#000;mix-blend-mode:difference}',
  '</style>',
  '</head>',
  '<body class="body" style="margin:0;padding:0;background:#0b0f14;background-image:linear-gradient(#0b0f14,#0b0f14);">',
  '<div class="gm-screen"><div class="gm-diff">',
  '<table role="presentation" width="100%" cellpadding="0" cellspacing="0" border="0" bgcolor="#0b0f14" style="background:#0b0f14;background-image:linear-gradient(#0b0f14,#0b0f14);">',
  '<tr><td align="center" style="padding:28px 12px;">',
  '<table role="presentation" width="100%" cellpadding="0" cellspacing="0" border="0" bgcolor="#111820" style="max-width:620px;background:#111820;background-image:linear-gradient(#111820,#111820);border:1px solid #1f6f8b;border-radius:10px;">',
  '<tr><td style="padding:28px 30px;font-family:\'Courier New\',Consolas,monospace;font-size:15px;line-height:1.6;color:#d7e3ea;">',
  inner,
  '</td></tr></table>',
  '</td></tr></table>',
  '</div></div>',
  '</body>',
  '</html>',
].join('\n');
return rows.map((r) => {
  const titulo = esc(r.o_que ?? r.rationale ?? r.code ?? 'Proposta');
  if (r.status === 'published') {
    const nums = versions.filter((v) => v.hermes_proposal_id === r.id).map((v) => Number(v.version)).filter(Number.isFinite);
    const v = nums.length ? String(Math.max(...nums)) : '?';
    return { json: {
      ids: [r.id],
      subject: '✅ PROTOCOLO HERMES // Atualização implantada — Malu v' + v + ' em campo',
      html: shell([
        '<p style="margin:0;color:#d7e3ea;"><b style="color:#38e1ff;">&gt; Implantação concluída.</b><br>',
        'A correção <i>"' + titulo + '"</i> está no ar. A Malu v' + v + ' já está atendendo.<br>',
        'O próximo lote de 50 conversas dirá se ela ficou mais forte. Se não ficou, eu recolho, corrijo, testo e só devolvo quando estiver validada.<br>',
        '<b style="color:#38e1ff;">&gt; Monitoramento contínuo ativo. Hermes, desligando.</b></p>',
      ].join('\n')),
    } };
  }
  return { json: {
    ids: [r.id],
    subject: '⚠️ PROTOCOLO HERMES // Atualização não publicada — ' + esc(r.code ?? 'proposta'),
    html: shell([
      '<p style="margin:0;color:#d7e3ea;"><b style="color:#ffb347;">&gt; Atualização não publicada.</b><br>',
      'A correção <i>"' + titulo + '"</i> não foi ao ar. A Malu continua na versão anterior.' + (r.result ? '<br>Resultado: ' + esc(r.result) : '') + '</p>',
    ].join('\n')),
  } };
});
